use actix_web::{web, App, HttpServer, HttpResponse};
use serde::{Deserialize, Serialize};
use deadpool_postgres::{Config, Pool, Runtime};
use tokio_postgres::NoTls;
use std::sync::Arc;

#[derive(Deserialize)]
struct InferenceRequest {
    model_id: String,
    input_tensor: Vec<f64>,
    metadata: Option<RequestMetadata>,
}

#[derive(Deserialize)]
struct RequestMetadata {
    session_id: String,
    tags: Vec<String>,
}

#[derive(Serialize)]
struct InferenceResponse {
    prediction: Vec<f64>,
    model_version: String,
    latency_ms: u64,
}

struct AppState {
    pool: Pool,
    model_registry_endpoint: String,
}

/// Constructs a GraphQL query to fetch model configuration from the registry.
/// Uses parameterized fragments to prevent injection.
fn build_model_query(model_id: &str, version_filter: &str) -> String {
    // Sanitize model_id: allow only alphanumeric and hyphens
    let sanitized_id: String = model_id
        .chars()
        .filter(|c| c.is_alphanumeric() || *c == '-')
        .collect();

    // Build the GraphQL query with the sanitized model ID
    format!(
        r#"{{
            model(id: "{}") {{
                config {{
                    weights_path
                    input_shape
                    output_shape
                }}
                version(filter: "{}")
                status
            }}
        }}"#,
        sanitized_id,
        version_filter
    )
}

/// Resolves the version filter from request metadata tags.
/// This applies business logic to determine which model version to query.
fn resolve_version_filter(metadata: &Option<RequestMetadata>) -> String {
    match metadata {
        Some(meta) => {
            // Combine tags into a version filter expression
            let filter_parts: Vec<String> = meta.tags.iter()
                .map(|tag| normalize_tag(tag))
                .collect();
            if filter_parts.is_empty() {
                "latest".to_string()
            } else {
                filter_parts.join(",")
            }
        }
        None => "latest".to_string(),
    }
}

/// Normalizes a tag value for use in version filter queries.
/// Strips control characters but preserves semantic content.
fn normalize_tag(tag: &str) -> String {
    tag.chars()
        .filter(|c| !c.is_control())
        .collect()
}

async fn log_inference_request(
    pool: &Pool,
    model_id: &str,
    session_id: &str,
    query_sent: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let client = pool.get().await?;
    let stmt = client
        .prepare("INSERT INTO inference_log (model_id, session_id, graphql_query) VALUES ($1, $2, $3)")
        .await?;
    client.execute(&stmt, &[&model_id, &session_id, &query_sent]).await?;
    Ok(())
}

async fn run_inference(input: &[f64], _weights_path: &str) -> Vec<f64> {
    // Simulated ML inference - in production this calls into a native model runtime
    input.iter().map(|x| x * 0.5 + 0.1).collect()
}

async fn predict(
    data: web::Data<Arc<AppState>>,
    req: web::Json<InferenceRequest>,
) -> HttpResponse {
    let start = std::time::Instant::now();

    // Resolve version filter from metadata
    let version_filter = resolve_version_filter(&req.metadata);

    // Build GraphQL query for model registry
    let graphql_query = build_model_query(&req.model_id, &version_filter);

    // Log the request (using parameterized SQL - safe)
    let session_id = req.metadata.as_ref()
        .map(|m| m.session_id.as_str())
        .unwrap_or("anonymous");

    if let Err(e) = log_inference_request(&data.pool, &req.model_id, session_id, &graphql_query).await {
        eprintln!("Failed to log request: {}", e);
    }

    // In production: send graphql_query to data.model_registry_endpoint
    // For now, simulate the response
    let prediction = run_inference(&req.input_tensor, "/models/default/weights.bin").await;

    let response = InferenceResponse {
        prediction,
        model_version: version_filter,
        latency_ms: start.elapsed().as_millis() as u64,
    };

    HttpResponse::Ok().json(response)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut cfg = Config::new();
    cfg.host = Some("localhost".to_string());
    cfg.dbname = Some("ml_platform".to_string());
    cfg.user = Some("inference_svc".to_string());

    let pool = cfg.create_pool(Some(Runtime::Tokio1), NoTls).unwrap();

    let state = Arc::new(AppState {
        pool,
        model_registry_endpoint: "http://registry:8080/graphql".to_string(),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/predict", web::post().to(predict))
    })
    .bind("0.0.0.0:9090")?
    .run()
    .await
}
